import sys

import numpy as np
import wgpu

SHADER = """
@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;

const W: u32 = {w}u;
const H: u32 = {h}u;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {{
    let x = id.x;
    let y = id.y;
    if (x >= W || y >= H) {{
        return;
    }}
    let xl = select(x - 1u, 0u, x == 0u);
    let xr = min(x + 1u, W - 1u);
    let yu = select(y - 1u, 0u, y == 0u);
    let yd = min(y + 1u, H - 1u);
    let s = 4u * src[y * W + x] + src[y * W + xl] + src[y * W + xr]
          + src[yu * W + x] + src[yd * W + x];
    dst[y * W + x] = s / 8u;
}}
"""


def parse(text):
    tokens = text.split()
    w, h, steps = int(tokens[0]), int(tokens[1]), int(tokens[2])
    cells = np.array(tokens[3:3 + w * h], dtype=np.uint32)
    if cells.size != w * h:
        raise ValueError("not enough cells")
    return w, h, steps, cells


def diffuse(w, h, steps, cells):
    if steps == 0:
        return cells.copy()
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()
    usage = (wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC
             | wgpu.BufferUsage.COPY_DST)
    size = w * h * 4
    bufs = [device.create_buffer(size=size, usage=usage) for _ in range(2)]
    device.queue.write_buffer(bufs[0], 0, np.ascontiguousarray(cells, dtype=np.uint32))

    module = device.create_shader_module(code=SHADER.format(w=w, h=h))
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"})
    layout = pipeline.get_bind_group_layout(0)
    groups = []
    for a, b in ((0, 1), (1, 0)):
        groups.append(device.create_bind_group(layout=layout, entries=[
            {"binding": 0, "resource": {"buffer": bufs[a], "offset": 0, "size": size}},
            {"binding": 1, "resource": {"buffer": bufs[b], "offset": 0, "size": size}},
        ]))

    gx, gy = (w + 15) // 16, (h + 15) // 16
    encoder = device.create_command_encoder()
    cpass = encoder.begin_compute_pass()
    cpass.set_pipeline(pipeline)
    for i in range(steps):
        cpass.set_bind_group(0, groups[i % 2])
        cpass.dispatch_workgroups(gx, gy, 1)
    cpass.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(bufs[steps % 2])
    return np.frombuffer(data, dtype=np.uint32, count=w * h).copy()


def main():
    with open(sys.argv[1]) as f:
        w, h, steps, cells = parse(f.read())
    out = diffuse(w, h, steps, cells).reshape(h, w)
    lines = [" ".join(map(str, row)) for row in out.tolist()]
    lines.append("SUM %d" % int(out.astype(np.uint64).sum()))
    sys.stdout.write("\n".join(lines) + "\n")
    sys.stdout.flush()


if __name__ == "__main__":
    main()
