import subprocess
import sys
from pathlib import Path

import numpy as np
import pytest

MAIN = Path(__file__).parent / "main.py"


def ref(g, steps):
    g = g.astype(np.int64)
    for _ in range(steps):
        p = np.pad(g, 1, mode="edge")
        g = (4 * g + p[1:-1, :-2] + p[1:-1, 2:] + p[:-2, 1:-1] + p[2:, 1:-1]) // 8
    return g


@pytest.mark.parametrize("w,h,steps", [(1, 1, 5), (5, 3, 0), (7, 1, 9), (1, 6, 9),
                                       (17, 33, 40), (512, 512, 30)])
def test_matches_reference(tmp_path, w, h, steps):
    rng = np.random.default_rng(w * 1000 + h)
    g = rng.integers(0, 1_000_001, size=(h, w))
    f = tmp_path / "in.txt"
    f.write_text(f"{w} {h} {steps}\n" + "\n".join(" ".join(map(str, r)) for r in g.tolist()) + "\n")
    out = subprocess.run([sys.executable, "-I", str(MAIN), str(f)], capture_output=True,
                         text=True, check=True).stdout.splitlines()
    exp = ref(g, steps)
    assert out[:-1] == [" ".join(map(str, r)) for r in exp.tolist()]
    assert out[-1] == f"SUM {exp.sum()}"
